mapper.select:
/* 케어 일정 목록 조회 */ SELECT S.SCHDL_SN , S.PET_SN , S.SCHDL_KND_CD , K.COM_CD_NM AS SCHDL_KND_CD_NM , S.SCHDL_DT , CASE WHEN S.HR_INPT_YN = 'Y' THEN TRUE ELSE FALSE END AS HR_INPT_YN , S.CKUP_TYPE_CD , T.COM_CD_NM AS CKUP_TYPE_CD_NM , S.HSPTL_NM , S.SCHDL_NM , S.MEMO_CN , S.CLDR_BADGE_COLR_CD , ( SELECT COUNT(*) FROM CKUP_RCD C WHERE C.SCHDL_SN = S.SCHDL_SN ) AS CKUP_RCD_CNT FROM SCHDL S LEFT JOIN COM_CD K ON K.COM_CD = S.SCHDL_KND_CD AND K.COM_CD_PRNT_SN IS NOT NULL LEFT JOIN COM_CD T ON T.COM_CD = S.CKUP_TYPE_CD AND T.COM_CD_PRNT_SN IS NOT NULL WHERE S.PET_SN = #{petSn} AND S.DEL_YN = 'N'
AND S.SCHDL_DT >= #{cond.fromYmd}
AND S.SCHDL_DT < DATE_ADD(#{cond.toYmd}, INTERVAL 1 DAY)
AND S.SCHDL_KND_CD = #{cond.schdlKndCd}
AND S.CKUP_TYPE_CD = #{cond.ckupTypeCd}
ORDER BY DATE(S.SCHDL_DT) , S.HR_INPT_YN DESC , S.SCHDL_DT , S.SCHDL_SN
LIMIT #{cond.size}

/* 공통코드 그룹의 하위 코드 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM COM_CD C
         JOIN COM_CD G
           ON G.COM_CD_SN = C.COM_CD_PRNT_SN
        WHERE G.COM_CD = #{prntComCd}
          AND G.COM_CD_PRNT_SN IS NULL
          AND C.COM_CD = #{comCd}
          AND C.USE_YN = 'Y'
       )

mapper.insert:
/* 케어 일정 등록 */
INSERT INTO SCHDL
     ( PET_SN
     , SCHDL_KND_CD
     , CLDR_BADGE_COLR_CD
     , SCHDL_SRC_CD
     , SCHDL_DT
     , SCHDL_NM
     , MEMO_CN
     , DEL_YN
     , HR_INPT_YN
     , HSPTL_NM
     , CKUP_TYPE_CD
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{petSn}
     , #{schdlKndCd}
     , #{cldrBadgeColrCd}
     , #{schdlSrcCd}
     , #{schdlDt}
     , #{schdlNm}
     , #{memoCn}
     , 'N'
     , #{hrInptYn}
     , #{hsptlNm}
     , #{ckupTypeCd}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 케어 일정 수정 */
UPDATE SCHDL
   SET PET_SN             = #{schedule.petSn}
     , SCHDL_KND_CD       = #{schedule.schdlKndCd}
     , CLDR_BADGE_COLR_CD = #{schedule.cldrBadgeColrCd}
     , SCHDL_DT           = #{schedule.schdlDt}
     , SCHDL_NM           = #{schedule.schdlNm}
     , MEMO_CN            = #{schedule.memoCn}
     , HR_INPT_YN         = #{schedule.hrInptYn}
     , HSPTL_NM           = #{schedule.hsptlNm}
     , CKUP_TYPE_CD       = #{schedule.ckupTypeCd}
     , MDFR_ID            = #{actorId}
     , MDFCN_DT           = NOW()
 WHERE SCHDL_SN = #{schedule.schdlSn}
   AND DEL_YN = 'N'

/* 케어 일정 삭제 처리 */
UPDATE SCHDL
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE SCHDL_SN = #{schdlSn}
   AND DEL_YN = 'N'

/* 일정에 연결된 반복 예방 관리의 반려동물 변경 */
UPDATE REPT_PRVNT_MNG
   SET PET_SN   = #{petSn}
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE CKUP_RCD_SN IN ( SELECT C.CKUP_RCD_SN
                          FROM CKUP_RCD C
                         WHERE C.SCHDL_SN = #{schdlSn} )
